SELECT ?taxonName ?taxon ?vernacular WHERE {
      VALUES ?taxonName { "Hydrochoerus hydrochaeris" "Caiman latirostris" "Myocastor coypus" "Blastocerus dichotomus" "Jacana jacana" }
      ?taxon wdt:P225 ?taxonName .
      OPTIONAL { ?taxon wdt:P1843 ?vernacular . FILTER(LANG(?vernacular) = "pt") }
    }
